import{_ as e,o as r,c as a,a3 as d}from"./chunks/framework.B7pF4b99.js";const f=JSON.parse('{"title":"原始規格與驗收紀錄","description":"","frontmatter":{},"headers":[],"relativePath":"history.md","filePath":"history.md","lastUpdated":1794203475000}'),h={name:"history.md"};function o(l,t,n,s,i,m){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="原始規格與驗收紀錄" tabindex="-1">原始規格與驗收紀錄 <a class="header-anchor" href="#原始規格與驗收紀錄" aria-label="Permalink to &quot;原始規格與驗收紀錄&quot;">​</a></h1><p>此處按開發順序保存規格。它們記錄「當時做了什麼」，不一定代表現在的架構；第一次閱讀建議先看左側主題章節。 Spec 33 以前的歷史 source link 若指向舊 <code>kernel/</code> 或 <code>user/</code> 路徑，固定指向 2026-11-07 重整前 commit <code>800a805</code>，以保留當時程式碼參照；目前目錄與 UI/kernel 邊界見 <a href="./SPEC-33-module-architecture.html">Spec 33</a>。</p><h2 id="cli-磁碟開機-2026-11-09" tabindex="-1">CLI 磁碟開機（2026-11-09） <a class="header-anchor" href="#cli-磁碟開機-2026-11-09" aria-label="Permalink to &quot;CLI 磁碟開機（2026-11-09）&quot;">​</a></h2><p><code>make run-disk</code> 交叉編譯核心並安裝到 WUFS0002。QEMU 透過 OpenSBI 進入唯讀 flash 載入器，再從磁碟的 <code>/boot/kernel.elf</code> 啟動 UART shell。使用 QEMU 8.2.2／OpenSBI 1.3 驗證了 PowerShell 啟動至 <code>wuwaos/&gt;</code>、CLI 指令、新磁碟開機、重啟讀回與無磁碟時停止開機。 <a href="./topics/boot.html">開機流程</a> · <a href="https://github.com/johnson931128/WUWAOS/blob/main/plan.md#cli-%E7%A3%81%E7%A2%9F%E9%96%8B%E6%A9%9F2026-11-09" target="_blank" rel="noreferrer">實作與驗收範圍</a> · <a href="https://github.com/johnson931128/WUWAOS/commit/7b0b3e2" target="_blank" rel="noreferrer">實作提交</a></p><h2 id="互動教學整理-2026-11-08" tabindex="-1">互動教學整理（2026-11-08） <a class="header-anchor" href="#互動教學整理-2026-11-08" aria-label="Permalink to &quot;互動教學整理（2026-11-08）&quot;">​</a></h2><p>網站以 HTML/CSS/Vue 加入 <a href="./topics/block-async.html">Block Async I/O</a>、<a href="./topics/file-descriptors.html">FD/OFD</a>、<a href="./topics/paging.html">換頁與 Swap</a>、<a href="./topics/journal.html">Journal 與安全替換</a> 的教學模型，按章節分別提交，搭配筆記引用、參數／欄位與函式對照。模型展示的是程式邏輯順序，不是即時 OS、效能量測或新 QEMU 驗收。</p><p>大型概念與狀態演示使用 DOM/CSS，自動排版的 Mermaid 僅保留在程式碼關聯與小流程；原始規格的圖片、流程與驗收仍保留歷史位置。第一輪不使用新靜態生成圖或第三方教科書圖片；瀏覽器互動與視覺驗收依使用者要求為 NOT_RUN。</p><h2 id="spec-33-之後的實作進度" tabindex="-1">Spec 33 之後的實作進度 <a class="header-anchor" href="#spec-33-之後的實作進度" aria-label="Permalink to &quot;Spec 33 之後的實作進度&quot;">​</a></h2><p>後續工作直接記錄於 <a href="https://github.com/johnson931128/WUWAOS/blob/main/plan.md" target="_blank" rel="noreferrer">詳細計畫</a>，不改寫舊規格的驗收紀錄。對照目前程式碼請讀 <a href="./CODE_GUIDE.html">程式碼導覽</a> 與主題章節。</p><table tabindex="0"><thead><tr><th>工作</th><th>目前狀態與紀錄</th></tr></thead><tbody><tr><td>第 1 階段：多 TTY/session</td><td>已完成 endpoint 世代 handle、獨立佇列與 OFD 路由；當時 UI 為單一 Terminal view（<a href="https://github.com/johnson931128/WUWAOS/commit/d89a8a7" target="_blank" rel="noreferrer">d89a8a7</a>）</td></tr><tr><td>2A：事件等待</td><td>已完成 TTY／pipe 的 caller-stack 等待與 idle 喚醒，scheduler poll 不執行 usercopy（<a href="https://github.com/johnson931128/WUWAOS/commit/f9e092b" target="_blank" rel="noreferrer">f9e092b</a>）</td></tr><tr><td>2B1：核心 gate</td><td>已完成 owner-aware gate、OFD／pipe、FS／VM 保護與延後取消；增量建置及基本 GUI smoke 已執行，額外邊界矩陣未執行（<a href="https://github.com/johnson931128/WUWAOS/commit/aa480e3" target="_blank" rel="noreferrer">aa480e3</a>）</td></tr><tr><td>2B2：非同步 Block</td><td>已實作 per-device gate／event／bounce、runtime 等待與 VM PTE rollback（<a href="https://github.com/johnson931128/WUWAOS/commit/eb84ff7" target="_blank" rel="noreferrer">eb84ff7</a>、<a href="https://github.com/johnson931128/WUWAOS/commit/7e0f826" target="_blank" rel="noreferrer">7e0f826</a>）</td></tr><tr><td>2C：GPU 非阻塞 present</td><td>已實作 CPU shadow／DMA backing 分離、dirty merge、transfer／flush poll（<a href="https://github.com/johnson931128/WUWAOS/commit/ea6671e" target="_blank" rel="noreferrer">ea6671e</a>）</td></tr><tr><td>第 3 階段：裝置復原</td><td>已實作 Block reset 後隔離、GPU 有界 reset／重建／停用（<a href="https://github.com/johnson931128/WUWAOS/commit/19be53a" target="_blank" rel="noreferrer">19be53a</a>、<a href="https://github.com/johnson931128/WUWAOS/commit/e48845b" target="_blank" rel="noreferrer">e48845b</a>）</td></tr><tr><td>第 4 階段：堆疊與生命週期</td><td>已實作 process／scheduler 未映射 guard page；生命週期靜態 review，沒有 emergency trap stack（<a href="https://github.com/johnson931128/WUWAOS/commit/b555d29" target="_blank" rel="noreferrer">b555d29</a>）</td></tr><tr><td>第 5 階段：四視窗</td><td>已實作獨立 TTY、z-order／focus、drag、裁切 viewport 與 close；固定 100×30 model（<a href="https://github.com/johnson931128/WUWAOS/commit/05b8124" target="_blank" rel="noreferrer">05b8124</a>）</td></tr><tr><td>第 6 階段：安全替換與診斷</td><td>已實作 fs_replace／Fan、新 ERR_UNCERTAIN 與 UART 診斷（<a href="https://github.com/johnson931128/WUWAOS/commit/496b757" target="_blank" rel="noreferrer">496b757</a>）；後續故障輸出整理見 <a href="https://github.com/johnson931128/WUWAOS/commit/6ef3029" target="_blank" rel="noreferrer">6ef3029</a>、<a href="https://github.com/johnson931128/WUWAOS/commit/3bc436d" target="_blank" rel="noreferrer">3bc436d</a></td></tr></tbody></table><p>2026-11-08 的 2B2、2C 與第 3–6 階段已完成一次必要整合編譯。依使用者要求未執行任何測試、未新增測試程式碼；所有新增 runtime／GUI／裝置故障與復原／重播均為 NOT_RUN。本次文件建置亦不代表 OS 驗收，詳細算法與限制以計畫為準。</p><h2 id="原始規格" tabindex="-1">原始規格 <a class="header-anchor" href="#原始規格" aria-label="Permalink to &quot;原始規格&quot;">​</a></h2><table tabindex="0"><thead><tr><th>階段</th><th>規格與定位</th></tr></thead><tbody><tr><td>01</td><td><a href="./SPEC-01-user-syscalls.html">使用者模式與系統呼叫</a></td></tr><tr><td>02</td><td><a href="./SPEC-02-process-lifecycle.html">合作式行程生命週期</a></td></tr><tr><td>03</td><td><a href="./SPEC-03-shell-pipe.html">Shell、PCB 與 Pipe</a></td></tr><tr><td>04</td><td><a href="./SPEC-04-boot-splash.html">開機 ASCII 動畫</a></td></tr><tr><td>05</td><td><a href="./SPEC.html">Fork → Exec → 排程 → 回收</a>，靜態位址空間設計已更新</td></tr><tr><td>06</td><td><a href="./SPEC-06-filesystem.html">VirtIO 與 WUFS</a></td></tr><tr><td>07</td><td><a href="./SPEC-07-fifo-scheduler.html">FIFO 排程器</a></td></tr><tr><td>08</td><td><a href="./SPEC-08-memory.html">動態實體頁與三級頁表</a>，預先載入使用者頁的部分由 10 取代</td></tr><tr><td>09</td><td><a href="./SPEC-09-fan.html">fan 全螢幕編輯器</a></td></tr><tr><td>10</td><td><a href="./SPEC-10-demand-paging.html">Demand paging、頁面置換與 Swap</a>，現行 VM 設計</td></tr><tr><td>11</td><td><a href="./SPEC-11-documentation.html">文件網站</a></td></tr><tr><td>12</td><td><a href="./SPEC-12-block-timeout.html">磁碟請求逾時與停止核心</a></td></tr><tr><td>13</td><td><a href="./SPEC-13-block-splash.html">螢光色塊開機字樣</a></td></tr><tr><td>14</td><td><a href="./SPEC-14-shell-help.html">逐行命令說明</a></td></tr><tr><td>15</td><td><a href="./SPEC-15-timer-rr.html">計時器中斷與 RR 排程</a>，現行 CPU 排程政策</td></tr><tr><td>16</td><td><a href="./SPEC-16-kernel-context.html">RV64 核心上下文切換</a>，獨立排程器堆疊、阻塞後恢復 C 呼叫</td></tr><tr><td>17</td><td><a href="./SPEC-17-workstate.html">workstate 即時監測</a>，CPU／RAM 快照、毫秒休眠與全螢幕操作</td></tr><tr><td>18</td><td><a href="./SPEC-18-file-commands.html">檔案命令與 cls</a>，刪除、複製、畫面與捲動歷史</td></tr><tr><td>19</td><td><a href="./SPEC-19-cwd-shell.html">工作目錄與 shell 命令處理</a>，每行程目錄、相對路徑</td></tr><tr><td>20</td><td><a href="./SPEC-20-directory-removal.html">資料夾刪除與確認</a>，子目錄與檔案回收</td></tr><tr><td>21</td><td><a href="./SPEC-21-native-compilation.html">系統內編譯 C 程式的長期目標</a>，目前為規劃、尚未實作</td></tr><tr><td>22</td><td><a href="./SPEC-22-synchronization.html">自製 Mutex 與 Semaphore</a>，單核心同步與驗證範圍</td></tr><tr><td>23</td><td><a href="./SPEC-23-sync-demo.html">同步工具互動示範</a>，實際行程與等待狀態</td></tr><tr><td>24</td><td><a href="./SPEC-24-demo-video.html">功能示範影片</a>，QEMU 實際操作與影片驗證</td></tr><tr><td>25</td><td><a href="./SPEC-25-process-capacity.html">行程容量擴充</a>，16 個行程、資源回收與 workstate 分頁</td></tr><tr><td>26</td><td><a href="./SPEC-26-elf-exec.html">WUFS 路徑式 ELF 載入</a>，受限靜態 RV64 使用者程式</td></tr><tr><td>27</td><td><a href="./SPEC-27-file-descriptors-and-shell-pipelines.html">檔案描述號、一般 I/O 與 Shell 管線</a>，FD/OFD、WUFS offset I/O、多階段管線與重導向</td></tr><tr><td>28</td><td><a href="./SPEC-28-native-desktop.html">原生 QEMU 圖形桌面與游標</a>，VirtIO GPU/tablet、1280×720 framebuffer 與 guest 游標驗收</td></tr><tr><td>29</td><td><a href="./SPEC-29-desktop-launcher.html">Windows 單指令桌面啟動器</a>，背景 QEMU、原生 VNC viewer、QMP 關閉與 Snapshot 磁碟隔離</td></tr><tr><td>30</td><td><a href="./SPEC-30-graphical-terminal.html">桌面 Terminal 與圖形 shell</a>，VirtIO keyboard/tablet、獨立 GUI TTY、ANSI 終端與 QEMU 驗收</td></tr><tr><td>31</td><td><a href="./SPEC-31-filesystem-initialization-guard.html">WUFS 非空白磁碟保護與固定驗證入口</a>，kernel／主機映像工具的格式化條件、獨立磁碟與 SHA-256 檢查；使用者已確認本項驗證</td></tr><tr><td>32</td><td><a href="./SPEC-32-wufs-redo-journal.html">WUFS0002 整磁區 redo journal 與安全儲存</a>，提交順序、重播、WUFS0001 唯讀相容、host image 安全替換與 QEMU fault 驗收</td></tr><tr><td>33</td><td><a href="./SPEC-33-module-architecture.html">核心模組分層與圖形終端解耦</a>，目前 source tree 與 UI、TTY、kernel、driver 的資料通道</td></tr></tbody></table><h2 id="如何判斷是否驗證過" tabindex="-1">如何判斷是否驗證過 <a class="header-anchor" href="#如何判斷是否驗證過" aria-label="Permalink to &quot;如何判斷是否驗證過&quot;">​</a></h2><p>請讀各規格的「驗收紀錄」及「限制與未驗證」。設計方案、原始碼靜態檢查、實際 QEMU 操作是不同種類的證據；沒有記錄的邊界不能當成已通過。</p><p>完整檔案職責與演算法見 <a href="./CODE_GUIDE.html">程式碼與架構紀錄</a>。</p>',16)])])}const p=e(h,[["render",o]]);export{f as __pageData,p as default};
